e:10px;text-transform:uppercase;color:var(--ex-muted);letter-spacing:.04em}.ex-item input{padding:7px 6px;width:100%;box-sizing:border-box;border:1px solid #d8deea;border-radius:5px}.ex-table{width:100%;border-collapse:collapse;font-size:12px}.ex-table th,.ex-table td{padding:11px 10px;border-bottom:1px solid var(--ex-line);text-align:left;vertical-align:middle}.ex-table th{font-size:10px;text-transform:uppercase;letter-spacing:.04em;color:var(--ex-muted);background:var(--ex-soft);white-space:nowrap}.ex-table tr:hover td{background:#fbfcfe}.ex-right{text-align:right!important}.ex-badge{display:inline-flex;padding:4px 8px;border-radius:20px;font-size:10px;font-weight:800;text-transform:capitalize}.draft{background:#eef1f5;color:#64748b}.submitted{background:#fff2cf;color:var(--ex-amber)}.posted{background:#e6f0ff;color:#2261b6}.paid{background:#e2f6ed;color:var(--ex-green)}.rejected{background:#fde8eb;color:var(--ex-red)}.ex-ghost{border:1px solid #d8deea;background:#fff;color:var(--ex-ink);border-radius:6px;padding:7px 10px;font-size:11px;font-weight:700;cursor:pointer}.ex-link{color:var(--ex-blue);font-weight:700;font-size:11px;cursor:pointer}.ex-note{background:#f5f8ff;border:1px solid #dbe7ff;color:#45618d;padding:11px 13px;border-radius:7px;font-size:11px;line-height:1.5}.ex-toolbar{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-bottom:12px}.ex-toolbar .ex-input{width:auto}.ex-empty{text-align:center;color:var(--ex-muted);padding:38px}.ex-chart{display:flex;align-items:flex-end;gap:13px;height:170px;padding:15px 5px 0;border-bottom:1px solid var(--ex-line)}.ex-bar{flex:1;background:#bcd5ff;border-radius:5px 5px 0 0;min-height:18px;position:relative}.ex-bar b{position:absolute;bottom:-22px;left:50%;transform:translateX(-50%);font-size:10px;color:var(--ex-muted)}.ex-bar em{position:absolute;top:-18px;left:50%;transform:translateX(-50%);font-size:9px;font-style:normal;color:var(--ex-muted)}.ex-modal{position:fixed;inset:0;background:#11213b66;display