<script>
window.exAllowed=<?php echo json_encode(array_values($exAllowed)); ?>;   // the live loaders read this; without it none of the screens below ever got real data
const exRows=[];
function exBadge(s){return '<span class="ex-badge '+s+'">'+s.replace('_',' ')+'</span>'}function exRow(r){return '<tr><td><b>'+r[0]+'</b><br><span style="color:var(--ex-muted)">'+r[1]+'</span></td><td>'+r[2]+'</td><td>'+r[3]+'</td><td>'+r[4]+'</td><td class="ex-right">'+r[5]+'</td><td>'+exBadge(r[6])+'</td><td><span class="ex-link">View</span></td></tr>'}document.getElementById('ex-recent').innerHTML=exRows.slice(0,4).map(exRow).join('');document.getElementById('ex-all').innerHTML=exRows.map(exRow).join('');
async function exHealth(){let box=document.getElementById('ex-health');box.innerHTML='<div style="padding:25px"><i class="fas fa-circle-notch fa-spin"></i> Checking database and Finance...</div>';try{let base=(typeof window.appBasePath!=='undefined'?window.appBasePath:(location.pathname.substring(0,location.pathname.lastIndexOf('/'))||''));let r=await fetch(base+'/api.php?endpoint=expenses/management&action=health');let j=await r.json();if(!j.success)throw new Error(j.message||'Request failed');let d=j.data;box.innerHTML='<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px"><b style="color:'+(d.ready?'var(--ex-green)':'var(--ex-red)')+'">'+(d.ready?'Ready: all checks passed':'Attention required: '+(d.total-d.passed)+' check(s) failed')+'</b><span style="font-size:11px;color:var(--ex-muted)">'+d.passed+'/'+d.total+' passed · '+d.tested_at+'</span></div><table class="ex-table"><thead><tr><th>Check</th><th>Result</th><th>Details</th></tr></thead><tbody>'+d.checks.map(c=>'<tr><td>'+c.name+'</td><td><span class="ex-badge '+(c.ok?'paid':'rejected')+'">'+(c.ok?'PASS':'FAIL')+'</span></td><td style="color:var(--ex-muted)">'+c.detail+'</td></tr>').join('')+'</tbody></table>'}catch(e){box.innerHTML='<div style="padding:20px;color:var(--ex-red)"><i class="fas fa-exclamation-triangle"></i> Could not reach the API: '+e.message+'</div>'}}
function exShow(v){document.querySelectorAll('.ex-view').forEach(x=>x.classList.remove('active'));document.getElementById('view-'+v).classList.add('active');document.querySelectorAll('#ex-nav button').forEach(x=>x.classList.toggle('active',x.dataset.view===v));window.scrollTo({top:0,behavior:'smooth'})}document.querySelectorAll('#ex-nav button').forEach(b=>b.onclick=()=>exShow(b.dataset.view));
function exAddItem(){let r=document.createElement('tr');r.innerHTML='<td><input placeholder="Item name"></td><td><input type="number" value="1"></td><td><input placeholder="unit"></td><td><input type="number" value="0" oninput="exTotal()"></td><td class="ex-right">0</td><td><button class="ex-ghost" onclick="this.closest(\'tr\').remove();exTotal()"><i class="fas fa-trash"></i></button></td>';document.getElementById('ex-items').appendChild(r)}function exTotal(){let t=0;document.querySelectorAll('#ex-items tr').forEach(r=>{let q=Number(r.children[1].querySelector('input').value||0),a=Number(r.children[3].querySelector('input').value||0),n=q*a;t+=n;r.children[4].textContent=n.toLocaleString()});document.getElementById('ex-total').textContent='RWF '+t.toLocaleString()}
function exModal(type){let title=type==='supplier'?'Create new supplier':'Create new expense category';document.getElementById('ex-modal-title').textContent=title;document.getElementById('ex-modal-body').innerHTML=type==='supplier'?'<div class="ex-formgrid"><div class="ex-field ex-full"><label>Supplier name *</label><input class="ex-input" placeholder="Company or payee name"></div><div class="ex-field"><label>Telephone</label><input class="ex-input"></div><div class="ex-field"><label>TIN</label><input class="ex-input"></div><div class="ex-field ex-full"><label>Email</label><input class="ex-input"></div><div class="ex-field ex-full"><label>Address</label><textarea class="ex-input" rows="2"></textarea></div></div><div class="ex-actions"><button class="ex-ghost" onclick="exClose()">Cancel</button><button class="ex-primary" onclick="exSaved(\'Supplier\')">Create supplier</button></div>':'<div class="ex-field"><label>Category name *</label><input class="ex-input" id="new-category" placeholder="e.g. Utilities"></div><div class="ex-field" style="margin-top:12px"><label>Default accounting treatment</label><select class="ex-input"><option>Expense account</option><option>Inventory asset</option><option>Employee advance asset</option><option>Prepaid expense asset</option><option>Fixed asset / capital improvement</option></select></div><div class="ex-actions"><button class="ex-ghost" onclick="exClose()">Cancel</button><button class="ex-primary" onclick="exSaved(\'Category\')">Save category</button></div>';document.getElementById('ex-modal').classList.add('open')}function exSaved(type){alert(type+' created. It will be available in the selector.');exClose()}function exClose(){document.getElementById('ex-modal').classList.remove('open')}
function exModal(type){let title=type==='supplier'?'Create new supplier':'Create new expense category';document.getElementById('ex-modal-title').textContent=title;document.getElementById('ex-modal-body').innerHTML=type==='supplier'?'<div class="ex-formgrid"><div class="ex-field ex-full"><label>Supplier name *</label><input class="ex-input" placeholder="Company or payee name"></div><div class="ex-field"><label>Telephone</label><input class="ex-input"></div><div class="ex-field"><label>TIN</label><input class="ex-input"></div><div class="ex-field ex-full"><label>Email</label><input class="ex-input"></div><div class="ex-field ex-full"><label>Address</label><textarea class="ex-input" rows="2"></textarea></div></div><div class="ex-actions"><button class="ex-ghost" onclick="exClose()">Cancel</button><button class="ex-primary" onclick="exSaved(\'Supplier\')">Create supplier</button></div>':'<div class="ex-field"><label>Category name *</label><input class="ex-input" id="new-category" placeholder="e.g. Utilities"></div><div class="ex-field" style="margin-top:12px"><label>Default accounting treatment</label><select class="ex-input"><option>Expense account</option><option>Inventory asset</option><option>Employee advance asset</option><option>Prepaid expense asset</option><option>Fixed asset / capital improvement</option></select></div><div class="ex-actions"><button class="ex-ghost" onclick="exClose()">Cancel</button><button class="ex-primary" onclick="exSaved(\'Category\')">Save category</button></div>';document.getElementById('ex-modal').classList.add('open')}function exSaved(type){alert(type+' created. It will be available in the selector.');exClose()}function exClose(){document.getElementById('ex-modal').classList.remove('open')}
 const $=id=>document.getElementById(id);const exLiveApi=((typeof window.appBasePath!=='undefined'?window.appBasePath:(location.pathname.substring(0,location.pathname.lastIndexOf('/'))||''))+'/api.php?endpoint=expenses/management');let exCategories=[],exSuppliers=[],exAccounts=[];
 async function exLive(action,body){let r=await fetch(exLiveApi+'&action='+action,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{});return r.json()}
 function exField(label){return [...document.querySelectorAll('#view-add .ex-field')].find(x=>x.querySelector('label')?.textContent.toLowerCase().includes(label))?.querySelector('input,select,textarea')}
 async function exLiveLoad(){try{let [c,s,a]=await Promise.all([window.exAllowed.includes('categories')?exLive('categories'):Promise.resolve({data:[]}),window.exAllowed.includes('suppliers')?exLive('suppliers'):Promise.resolve({data:[]}),window.exAllowed.includes('add')?exLive('accounts'):Promise.resolve({data:[]})]);exCategories=c.data||[];exSuppliers=s.data||[];exAccounts=a.data||[];let cat=$('ex-category'),sup=$('ex-supplier');if(cat)cat.innerHTML=exCategories.map(x=>`<option value="${x.id}" data-account="${x.account_id||''}">${exEsc(x.name)}</option>`).join('');if(sup)sup.innerHTML='<option value="">— Select supplier —</option>'+exSuppliers.map(x=>`<option value="${x.id}" data-name="${exEsc(x.company_name)}">${exEsc(x.company_name)}</option>`).join('');let list=await exLive('list');let rows=list.data||[];let tb=document.getElementById('ex-all');if(tb)tb.innerHTML=rows.length?rows.map(x=>`<tr><td><b>${exEsc(x.expense_no)}</b><br><span style="color:var(--ex-muted)">${exEsc(x.expense_date)}</span></td><td>${exEsc(x.supplier_name||x.payee||'—')}</td><td>${exEsc(x.category_name||'—')}</td><td>${exEsc(x.description)}</td><td class="ex-right">${Number(x.total).toLocaleString()}</td><td>${exBadge(x.status)}</td><td><button class="ex-ghost" onclick="exLiveView(${x.id})">View</button>${['posted','partially_paid'].includes(x.status)?` <button class="ex-ghost" onclick="exLivePay(${x.id},${x.total-x.amount_paid})">Pay</button>`:''}</td></tr>`).join(''):'<tr><td colspan="8" class="ex-empty">No expenses recorded.</td></tr>';exRenderCategories();exRenderSuppliers()}catch(e){console.error(e)}}
 function exEsc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
 function exRenderCategories(){let t=document.querySelector('#view-categories tbody');if(!t)return;t.innerHTML=exCategories.map(x=>`<tr><td><b>${exEsc(x.name)}</b></td><td>${exEsc(x.account_name||'Not mapped')}</td><td>Configured by hospital</td><td><span class="ex-badge paid">Active</span></td><td><button class="ex-ghost" onclick="exCategoryEdit(${x.id},'${exEsc(x.name)}',${x.account_id||0})">Edit</button> <button class="ex-ghost" onclick="exCategoryDeactivate(${x.id})">Deactivate</button></td></tr>`).join('')}
 function exRenderSuppliers(){let t=document.querySelector('#view-suppliers tbody');if(!t)return;t.innerHTML=exSuppliers.map(x=>`<tr><td><b>${exEsc(x.company_name)}</b></td><td>${exEsc(x.phone||'—')}<br>${exEsc(x.email||'')}</td><td>${exEsc(x.tax_id||'—')}</td><td class="ex-right">—</td><td><span class="ex-badge paid">Active</span></td><td><span class="ex-link">View expenses</span></td></tr>`).join('')}
 async function exCategoryEdit(id,name,account){let n=prompt('Category name:',name);if(n===null)return;let j=await exLive('category_update',{id,name:n,account_id:account||exAccounts[0]?.id});alert(j.message);if(j.success)exLiveLoad()}
 async function exCategoryDeactivate(id){if(!confirm('Deactivate this expense category?'))return;let j=await exLive('category_deactivate',{id});alert(j.message);if(j.success)exLiveLoad()}
 async function exLiveView(id){let j=await exLive('view&id='+id);if(!j.success)return alert(j.message);let x=j.data.expense;alert(`${x.expense_no}\n${x.description}\nSupplier: ${x.supplier_name||x.payee||'—'}\nTotal: ${Number(x.total).toLocaleString()} RWF\nStatus: ${x.status}\nDocuments: ${(j.data.documents||[]).length}\nHistory: ${(j.data.history||[]).map(h=>h.action).join(' → ')}`)}
 async function exLivePay(id,balance){let amount=prompt('Payment amount (balance '+Number(balance).toLocaleString()+' RWF):',balance);if(amount===null)return;let ca=await exLive('cash_accounts'),aid=prompt((ca.data||[]).map(x=>x.id+' = '+x.account_name).join('\n')+'\nEnter payment account ID');if(!aid)return;let j=await exLive('pay',{id,amount,pay_account_id:aid,payment_date:new Date().toISOString().slice(0,10),method:'bank_transfer',reference:'UI-PAY-'+Date.now()});alert(j.message);if(j.success)exLiveLoad()}
 async function exSaved(type){if(type==='Supplier'){let i=document.querySelectorAll('#ex-modal-body input, #ex-modal-body textarea'),j=await exLive('supplier',{company_name:i[0]?.value,phone:i[1]?.value,tax_id:i[2]?.value,email:i[3]?.value,address:i[4]?.value});alert(j.message);if(j.success){exClose();exLiveLoad()}return}let name=document.getElementById('new-category')?.value.trim();if(!name)return alert('Category name is required');let j=await exLive('category',{name,account_id:exAccounts[0]?.id});alert(j.message);if(j.success){exClose();exLiveLoad()}}
async function exLiveSave(submit){let cat=document.getElementById('ex-category'),sup=document.getElementById('ex-supplier'),items=[...document.querySelectorAll('#ex-items tr')].map(r=>({item_service:r.children[0].querySelector('input').value,quantity:r.children[1].querySelector('input').value,unit:r.children[2].querySelector('input').value,unit_price:r.children[3].querySelector('input').value}));let b={expense_date:exField('expense date')?.value,category_id:cat?.value,supplier_id:sup?.value,expense_account_id:cat?.selectedOptions[0]?.dataset.account||exAccounts[0]?.id,description:exField('purpose')?.value||'',invoice_reference:exField('invoice')?.value||'',items,payee:sup?.selectedOptions[0]?.dataset.name||'',comments:document.querySelector('#view-add textarea')?.value||'',payment_method:document.getElementById('ex-method')?.value||''};let j=await exLive('save',b);if(!j.success)return alert(j.message);if(document.getElementById('ex-files')?.files.length)for(let f of document.getElementById('ex-files').files){let fd=new FormData();fd.append('expense_id',j.data.id);fd.append('file',f);await fetch(exLiveApi+'&action=upload',{method:'POST',body:fd})}if(submit){let s=await exLive('submit',{id:j.data.id});if(!s.success)return alert(s.message)}alert(submit?'Expense submitted for approval':'Draft saved');exLiveLoad()}
 document.querySelectorAll('#view-add .ex-actions button').forEach(b=>{if(b.textContent.includes('Save &'))b.onclick=()=>exLiveSave(true);else if(b.textContent.includes('Save draft'))b.onclick=()=>exLiveSave(false)});let note=document.querySelector('#view-add textarea');if(note&&!document.getElementById('ex-payment-fields'))note.insertAdjacentHTML('beforebegin','<div id="ex-payment-fields" class="ex-formgrid" style="margin:12px 0"><div class="ex-field"><label>Payment method</label><select class="ex-input" id="ex-method"><option value="">Unpaid / payable</option><option value="cash">Cash</option><option value="bank_transfer">Bank transfer</option><option value="mobile_money">Mobile money</option><option value="check">Cheque</option><option value="other">Other</option></select></div><div class="ex-field"><label>Payment status</label><select class="ex-input" id="ex-pay-status"><option>Unpaid</option><option>Partially paid</option><option>Paid</option></select></div><div class="ex-field"><label>Payment date</label><input class="ex-input" type="date" id="ex-pay-date"></div><div class="ex-field"><label>Transaction reference</label><input class="ex-input" id="ex-pay-ref"></div></div>');document.querySelectorAll('#view-add .ex-card').forEach(c=>{if(c.textContent.includes('Evidence')&&!document.getElementById('ex-files'))c.insertAdjacentHTML('beforeend','<input id="ex-files" type="file" multiple accept="application/pdf,image/jpeg,image/png,image/webp" style="margin-top:12px;width:100%">')});exShow('<?php echo $exSub; ?>');exLiveLoad();
 </script>
<script>
// Live management controls: filters, approvals, cancellation and report actions.
function exLiveRowsFilter(){let q=document.querySelector('#view-expenses .ex-toolbar input')?.value.toLowerCase()||'',st=document.querySelector('#view-expenses .ex-toolbar select')?.value||'';document.querySelectorAll('#ex-all tr').forEach(r=>{let text=r.textContent.toLowerCase();r.style.display=(!q||text.includes(q))&&(!st||text.includes(st.replace('_',' ')))?'':'none'})}
document.querySelector('#view-expenses .ex-toolbar input')?.addEventListener('input',exLiveRowsFilter);document.querySelector('#view-expenses .ex-toolbar select')?.addEventListener('change',exLiveRowsFilter);
document.querySelectorAll('#view-reports .ex-ghost').forEach(b=>b.addEventListener('click',()=>window.print()));
const exInitialLoad=exLiveLoad;exLiveLoad=async function(){await exInitialLoad();let j=await exLive('list'),rows=j.data||[];let recent=document.getElementById('ex-recent');if(recent)recent.innerHTML=rows.slice(0,5).map(x=>`<tr><td><b>${exEsc(x.expense_no)}</b><br><span style="color:var(--ex-muted)">${exEsc(x.expense_date)}</span></td><td>${exEsc(x.supplier_name||x.payee||'—')}</td><td>${exEsc(x.category_name||'—')}</td><td class="ex-right">${Number(x.total).toLocaleString()}</td><td>${exBadge(x.status)}</td></tr>`).join('')||'<tr><td colspan="5" class="ex-empty">No expenses recorded.</td></tr>';let ap=document.querySelector('#view-approvals tbody'),pending=rows.filter(x=>x.status==='submitted');document.querySelectorAll('#ex-pending-count,#ex-dashboard-pending-count,#ex-dashboard-pending-count-2').forEach(e=>e.textContent=pending.length);if(ap)ap.innerHTML=pending.map(x=>`<tr><td><b>${exEsc(x.expense_no)}</b><br>${exEsc(x.expense_date)}</td><td>${exEsc(x.payee||x.supplier_name||'—')}</td><td>${exEsc(x.description)}</td><td class="ex-right">${Number(x.total).toLocaleString()}</td><td>${exBadge(x.status)}</td><td><button class="ex-primary" onclick="exApprove(${x.id})">Approve</button> <button class="ex-ghost" onclick="exReject(${x.id})">Reject</button></td></tr>`).join('')||'<tr><td colspan="6" class="ex-empty">No pending approvals.</td></tr>'};async function exApprove(id){let j=await exLive('approve',{id});alert(j.message);if(j.success)exLiveLoad()}async function exReject(id){let reason=prompt('Reason for rejection:');if(reason===null)return;let j=await exLive('reject',{id,reason});alert(j.message);if(j.success)exLiveLoad()}// Dashboard cards, Payments and Reports are worked out from the expense list (cancelled and rejected requests do not count)
const exPrevLive=exLiveLoad;exLiveLoad=async function(){await exPrevLive();
 let j=await exLive('list'),rows=(j.data||[]).filter(x=>!['rejected','cancelled','draft'].includes(x.status));if(!j.success)return;
 const money=n=>'RWF '+Number(n).toLocaleString(undefined,{maximumFractionDigits:0}),ym=d=>String(d||'').slice(0,7),now=new Date().toISOString().slice(0,7),set=(id,v)=>{let e=document.getElementById(id);if(e)e.textContent=v};
 const month=rows.filter(x=>ym(x.expense_date)===now),sum=a=>a.reduce((s,x)=>s+Number(x.total),0),sub=(j.data||[]).filter(x=>x.status==='submitted'),unpaid=rows.filter(x=>['posted','partially_paid'].includes(x.status));
 set('ex-m-total',money(sum(month)));set('ex-m-total-n',month.length+' expense request'+(month.length===1?'':'s'));
 set('ex-m-pend',money(sum(sub)));set('ex-m-unpaid',money(unpaid.reduce((s,x)=>s+Number(x.total)-Number(x.amount_paid||0),0)));set('ex-m-unpaid-n',unpaid.length+' approved expense'+(unpaid.length===1?'':'s'));
 set('ex-m-paid',money(month.reduce((s,x)=>s+Number(x.amount_paid||0),0)));
 set('ex-m-oldest',sub.length?sub.map(x=>x.expense_date).sort()[0]:'—');
 let pay=document.getElementById('ex-pay-rows');if(pay){let p=rows.filter(x=>Number(x.amount_paid)>0).sort((a,b)=>String(b.last_payment_date).localeCompare(String(a.last_payment_date)));
  pay.innerHTML=p.length?p.map(x=>`<tr><td>${exEsc(x.last_payment_date||'—')}</td><td><b>${exEsc(x.expense_no)}</b></td><td>${exEsc(x.supplier_name||x.payee||'—')}</td><td>${exEsc(x.payment_method||'—')}</td><td>${exEsc(x.last_payment_reference||'—')}</td><td class="ex-right">${Number(x.amount_paid).toLocaleString()}</td></tr>`).join(''):'<tr><td colspan="6" class="ex-empty">No payments recorded.</td></tr>'}
 const top=(key)=>{let m={};month.forEach(x=>{let k=x[key]||'—';m[k]=(m[k]||0)+Number(x.total)});let e=Object.entries(m).sort((a,b)=>b[1]-a[1])[0];return e||null};
 let c=top('category_name'),s=top('supplier_name')||top('payee');set('ex-rep-cat',c?c[0]:'—');set('ex-rep-cat-v',c?money(c[1])+' this month':'No expenses this month');set('ex-rep-sup',s?s[0]:'—');set('ex-rep-sup-v',s?money(s[1])+' this month':'No expenses this month');
 let chart=document.getElementById('ex-rep-chart');if(chart){let months=[];for(let i=4;i>=0;i--){let d=new Date();d.setDate(1);d.setMonth(d.getMonth()-i);months.push(d.toISOString().slice(0,7))}
  let tot=months.map(m=>sum(rows.filter(x=>ym(x.expense_date)===m))),max=Math.max(...tot,1);
  chart.innerHTML=months.map((m,i)=>`<div class="ex-bar" style="height:${Math.max(4,Math.round(tot[i]/max*100))}%${m===now?';background:#1769e0':''}"><em>${tot[i]>=1e6?(tot[i]/1e6).toFixed(1)+'m':Math.round(tot[i]/1e3)+'k'}</em><b>${new Date(m+'-15').toLocaleString('en',{month:'short'})}</b></div>`).join('')}
};exLiveLoad();
</script>
